import { JsonView, Card, Badge, Segmented } from "march/ui"

// bir API yanıtını incelemek: uç noktayı seç, yanıt ağaç olarak açılır; Türkçe sayım metinleri
const RESPONSES: Record<string, unknown> = {
  "/users/7": { id: 7, name: "Ada Yılmaz", email: "ada@ornek.com", roles: ["admin", "editor"], lastLogin: "2026-11-18T08:30:00Z", manager: null },
  "/orders?limit=2": { total: 128, page: 1, data: [{ id: 48210, sum: 1249.3, paid: true }, { id: 48211, sum: 89.9, paid: false }] },
  "/health": { ok: true, uptime: 86400, services: { db: "up", cache: "up", mail: "degraded" } },
}

export function ApiResponse() {
  let $url = "/users/7"
  return <Card title="İstek" actions={<Badge tone="success">200 OK</Badge>}>
    <Segmented label="Uç nokta" options={Object.keys(RESPONSES)} bind:value={$url} />
    <JsonView label="Yanıt" open={1} value={() => RESPONSES[$url]} labels={{ items: "öğe", keys: "alan" }} />
  </Card>
}

import { JsonView, Card } from "march/ui"

// JsonView'un bütün özellikleri bir arada: value (her tür: sayı, metin, null, dizi, tarih, döngüsel, işlev),
// open, labels, arrow (ok / yok / kendi), label, describe ve class
const data: Record<string, unknown> = {
  name: "March", version: 2, stable: true, author: null, tags: ["tsx", "signals"],
  since: new Date(Date.UTC(2026, 0, 1)), nested: { deep: { deeper: { deepest: "dip" } } },
  onClick: () => 1,
}
data.self = data

// bir ağaç ve üstünde adı
const Box = (props: { title: string; children?: unknown }) => <div sx={{ flex: "col", gap: 1 }}>
  <span sx={{ text: "xs", color: "muted" }}>{props.title}</span>
  {props.children}
</div>

export function JsonViewLab() {
  return <div sx={{ flex: "col", gap: 3 }}>
    <Box title="Her tür değer, iki kat açık, kendi metinler, işlevin adı">
      <JsonView class="lab-json" label="Paket" value={data} open={2}
        labels={{ items: "öğe", keys: "alan", circular: "(kendisi)" }}
        describe={(v: unknown) => typeof v === "function" ? "ƒ işlev" : null} />
    </Box>
    <Box title="Kapalı, kendi işaretim">
      <JsonView label="Kapalı" value={{ a: 1, b: [1, 2, 3] }} open={0} arrow={(open: () => boolean) => <b>{() => (open() ? "−" : "+")}</b>} />
    </Box>
    <Card m:theme="night">
      <Box title="Oksuz, koyu zemin">
        <JsonView label="Koyu" value={[1, "iki", { üç: 3 }]} arrow={false} />
      </Box>
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { JsonViewLab } from "./JsonViewLab.tsx"

// JsonViewLab'in testleri: kaydedince Testler sekmesinde çalışır
test("ağaç role=tree ve label adıyla", () => {
  const s = renderTest(() => <JsonViewLab />)
  const tree = s.get(".lab-json [role=tree]")!
  expect(tree.getAttribute("aria-label")).toBe("Paket")
})

test("describe işlevi adlandırır, döngü kendi metniyle yazılır", () => {
  const s = renderTest(() => <JsonViewLab />)
  const text = s.get(".lab-json")!.textContent!
  expect(text).toContain("ƒ işlev")
  expect(text).toContain("(kendisi)")
  expect(text).toContain("\"tsx\"")
})

test("open={0} kapalı başlar, tıklayınca açılır", async () => {
  const s = renderTest(() => <JsonViewLab />)
  const trees = s.all(".m-json")
  const btn = trees[1].querySelector(".m-json-toggle")!
  expect(btn.getAttribute("aria-expanded")).toBe("false")
  await s.click(btn)
  expect(btn.getAttribute("aria-expanded")).toBe("true")
})

test("kapalı dal labels.keys ile sayılır", () => {
  const s = renderTest(() => <JsonViewLab />)
  expect(s.get(".lab-json")!.textContent).toContain("1 alan")
})
